import { booleanAttribute, Component, computed, input } from '@angular/core';

/** Width (px) of the smaller and larger JPEG generated by `scripts/resize-photos.sh`. */
const SMALL = 800;
const LARGE = 1600;

/**
 * Renders a real photo when `src` is set, and a labelled placeholder until the photo exists.
 *
 * `src` is the path below `public/` without size suffix or extension (e.g. `images/groot-gebouw`);
 * the `-800.jpg` and `-1600.jpg` variants are offered to the browser as a `srcset`.
 */
@Component({
  selector: 'app-photo',
  styleUrl: './photo.scss',
  template: `
    @if (src(); as source) {
      <img
        [src]="'/' + source + '-' + small + '.jpg'"
        [attr.srcset]="srcset()"
        [attr.sizes]="sizes()"
        [alt]="alt()"
        width="800"
        height="600"
        [attr.loading]="priority() ? 'eager' : 'lazy'"
        [attr.fetchpriority]="priority() ? 'high' : null"
        decoding="async"
      />
    } @else {
      <div class="placeholder" role="img" [attr.aria-label]="alt()">
        <svg viewBox="0 0 24 24" width="40" height="40" aria-hidden="true">
          <path
            fill="currentColor"
            d="M9 3 7.2 5H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-3.2L15 3H9Zm3 5a5 5 0 1 1 0 10 5 5 0 0 1 0-10Zm0 2a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z"
          />
        </svg>
        <span>{{ alt() }}</span>
      </div>
    }
  `,
})
export class Photo {
  protected readonly small = SMALL;

  readonly src = input<string | null>(null);
  readonly alt = input.required<string>();
  /** Layout width of the photo, so the browser can pick the right file. */
  readonly sizes = input(
    '(min-width: 76rem) 363px, (min-width: 64rem) calc((100vw - 128px) / 3), (min-width: 53rem) calc((100vw - 80px) / 3), (min-width: 35.5rem) calc(50vw - 28px), calc(100vw - 32px)',
  );
  /** Load immediately instead of lazily; use for the photo at the top of the page. */
  readonly priority = input(false, { transform: booleanAttribute });

  protected readonly srcset = computed(() => {
    const source = this.src();
    return source ? `/${source}-${SMALL}.jpg ${SMALL}w, /${source}-${LARGE}.jpg ${LARGE}w` : null;
  });
}
